import{_ as p,a0 as d,w as a,s as l,ao as e,I as r,x as n,a1 as t,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Linux有問必答：如何在Linux命令列中刻錄ISO或NRG鏡像到DVD | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：如何在Linux命令列中刻錄ISO或NRG鏡像到DVD | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：如何在Linux命令列中刻錄ISO或NRG鏡像到DVD | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：如何在Linux命令列中刻錄ISO或NRG鏡像到DVD | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20141014 Linux FAQs with Answers--How to burn an ISO or NRG image to a DVD from the command line on Linux","title":"Linux有問必答：如何在Linux命令列中刻錄ISO或NRG鏡像到DVD","tag":"201410","desc":""},"relativePath":"201410/20141014 Linux FAQs with Answers--How to burn an ISO or NRG image to a DVD from the command line on Linux.md","filePath":"[post].md"}'),m={name:"201410/20141014 Linux FAQs with Answers--How to burn an ISO or NRG image to a DVD from the command line on Linux.md"};function u(g,o,D,f,x,_){const i=d("Link");return a(),l("div",null,[o[19]||(o[19]=e(`<h1 id="linux有問必答-如何在linux命令列中刻錄iso或nrg鏡像到dvd" tabindex="-1">Linux有問必答：如何在Linux命令列中刻錄ISO或NRG鏡像到DVD <a class="header-anchor" href="#linux有問必答-如何在linux命令列中刻錄iso或nrg鏡像到dvd" aria-label="Permalink to “Linux有問必答：如何在Linux命令列中刻錄ISO或NRG鏡像到DVD”">​</a></h1><blockquote><p><strong>問題</strong>：我需要在Linux機器上使用DVD刻錄機刻錄一個鏡像文件（.iso或.nrg）到DVD，有沒有一個既快捷又簡易的方法，最好是使用命令列工具？</p></blockquote><p>最常見的兩種鏡像文件格式是ISO（.iso為文件擴展名）和NRG（.nrg為文件擴展名）。ISO格式是一個由ISO（國際標準組織）創立的全球標準，因此被大多數操作系統所支持，它提供了很高的便攜性。另一方面，NRG格式是由Nero AG開發的私有格式，Nero AG是一個很流行的磁盤鏡像和刻錄軟件公司。</p><p>下面來解答怎樣從Linux命令列刻錄.iso或.nrg鏡像到DVD。</p><h3 id="刻錄-iso鏡像文件到dvd" tabindex="-1">刻錄.ISO鏡像文件到DVD <a class="header-anchor" href="#刻錄-iso鏡像文件到dvd" aria-label="Permalink to “刻錄.ISO鏡像文件到DVD”">​</a></h3><p>要刻錄.iso鏡像文件到DVD，我們將使用<strong>growisofs</strong>這個工具：</p><pre><code> # growisofs -dvd-compat -speed=4 -Z /dev/dvd1=WindowsXPProfessionalSP3Original.iso 
</code></pre><p>在上面的命令列中，“-dvd-compat”選項提供了與DVD-ROM/-Video的最大介質兼容性。在一次寫入式 DVD+R 或 DVD-R 上下文中，導致不可添加記錄（關閉磁盤）。</p><p>“-Z /dev/dvd1=filename.iso”選項表示我們刻錄.iso文件到設備選單（/dev/dvd1）中選擇的介質中。</p><p>“-speed=N”參數指定了DVD刻錄機的刻錄速度，這與驅動自身的能力直接相關。“-speed=8”將以8x刻錄，“-speed=16”將以16x刻錄，以此類推。沒有該參數，growisofs將默認以最低速刻錄，在這裏是4x。你可以根據你刻錄機的可用速度和磁盤類型選擇合適的刻錄速度。</p>`,10)),r("p",null,[o[1]||(o[1]=n("你可以根據",-1)),t(i,{href:"http://linux.cn/article-4081-1.html"},{default:s(()=>[...o[0]||(o[0]=[n("此教程",-1)])]),_:1}),o[2]||(o[2]=n("找出你的DVD刻錄機的設備名稱和它所支持的寫入速度。",-1))]),o[20]||(o[20]=e(`<p><img src="https://farm3.staticflickr.com/2947/15510172352_5c09c2f495_z.jpg" alt=""></p><p>刻錄進程完成後，磁盤會自動彈出。</p><h3 id="把nrg鏡像轉換為iso格式" tabindex="-1">把NRG鏡像轉換為ISO格式 <a class="header-anchor" href="#把nrg鏡像轉換為iso格式" aria-label="Permalink to “把NRG鏡像轉換為ISO格式”">​</a></h3><p>由於ISO被廣為採用，刻錄.iso鏡像到CD/DVD就非常簡單。但是，要刻錄一個.nrg鏡像則首先需要將它轉換為.iso格式。</p><p>把一個.nrg鏡像文件轉換到.iso格式，你可以使用nrg2iso這個工具。它是一個開源程序，用來將Nero Burning Rom創建的鏡像轉換到標準的.iso（ISO9660）文件。</p><p>在Debian及其衍生版上安裝<strong>nrg2iso</strong>：</p><pre><code># aptitude install nrg2iso
</code></pre><p>在基於Red Hat的發行版上安裝<strong>nrg2iso</strong>：</p><pre><code># yum install nrg2iso 
</code></pre>`,9)),r("p",null,[o[4]||(o[4]=n("在CentOS/RHEL上，你需要先啓用",-1)),t(i,{href:"http://xmodulo.com/how-to-set-up-rpmforge-repoforge-repository-on-centos.html"},{default:s(()=>[...o[3]||(o[3]=[n("Repoforge倉庫",-1)])]),_:1}),o[5]||(o[5]=n("，再通過",-1)),o[6]||(o[6]=r("strong",null,"yum",-1)),o[7]||(o[7]=n("安裝。",-1))]),o[21]||(o[21]=e(`<p>安裝完nrg2iso包後，使用以下命令來將.nrg鏡像轉換到.iso格式：</p><pre><code># nrg2iso filename.nrg filename.iso 
</code></pre><p><img src="https://farm3.staticflickr.com/2945/15507409981_99eddd2577_z.jpg" alt=""></p><p>轉換完成後，在當前目錄中會出現一個.iso文件：</p><p><img src="https://farm4.staticflickr.com/3945/15323823510_c933d7710f_z.jpg" alt=""></p><p>###檢查已刻錄介質的完整性###</p><p>關於這一點，你可以通過將刻錄的DVD的校驗和與原始.iso文件的md5校驗和進行對比，以檢查所刻錄介質的完整性。如果兩者相同，你就可以放心了，因為刻錄成功了。</p><p>然而，當你使用nrg2iso來將.nrg鏡像轉換為.iso格式後，你需要明白一點，nrg2iso創建的.iso文件的大小不是2048的倍數（通常，.iso文件的大小是它的倍數）。因此，常規的校驗和對比，該.iso文件和刻錄介質的內容不一樣。</p><p>另一方面，如果你已經刻錄了一個不是由.nrg文件轉換而來的.iso鏡像，你可以使用以下命令來檢查記錄到DVD中的數據的完整性。替換“/dev/dvd1”為你的設備名。</p><pre><code># md5sum filename.iso; dd if=/dev/dvd1 bs=2048 count=$(($(stat -c &quot;%s&quot; filename.iso) / 2048)) | md5sum 
</code></pre><p>命令的第一部分計算.iso文件的md5校驗和，而第二部分則讀取/dev/dvd1中的磁盤內容，然後通過管道輸出給md5sum工具。“bs=2048”表示dd命令將使用2048字節塊為單位檢查，因為原始iso文件以2048為單位劃分。</p><p><img src="https://farm3.staticflickr.com/2949/15487396726_bcf47d536f_z.jpg" alt=""></p><p>如果兩個md5校驗和的值相同，這就意味着刻錄的介質是有效的。</p><hr>`,14)),r("p",null,[o[9]||(o[9]=n("via: ",-1)),t(i,{href:"http://ask.xmodulo.com/burn-iso-nrg-image-dvd-command-line.html"},{default:s(()=>[...o[8]||(o[8]=[n("http://ask.xmodulo.com/burn-iso-nrg-image-dvd-command-line.html",-1)])]),_:1})]),r("p",null,[o[12]||(o[12]=n("譯者：",-1)),t(i,{href:"https://github.com/GOLinux"},{default:s(()=>[...o[10]||(o[10]=[n("GOLinux",-1)])]),_:1}),o[13]||(o[13]=n(" 校對：",-1)),t(i,{href:"https://github.com/carolinewuyan"},{default:s(()=>[...o[11]||(o[11]=[n("Caroline",-1)])]),_:1})]),r("p",null,[o[16]||(o[16]=n("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...o[14]||(o[14]=[n("LCTT",-1)])]),_:1}),o[17]||(o[17]=n(" 原創翻譯，",-1)),t(i,{href:"http://linux.cn/"},{default:s(()=>[...o[15]||(o[15]=[n("Linux中國",-1)])]),_:1}),o[18]||(o[18]=n(" 榮譽推出",-1))])])}const S=p(m,[["render",u]]);export{T as __pageData,S as default};
